#include <stdio.h>

void main()
{
    printf("Let's calculate!\n");
    printf("1234 + 4321 =  %5d\n", 1234 + 4321);
    printf("2 * 3.1415 =  %7.1f\n", 2 * 3.1415);
    printf("5 / 2 = %d\n", 5 / 2); /* integer division */
    printf("5.0 / 2 = %f\n", 5.0 / 2); /* type conversion */
    printf("5 %% 2 = %d\n", 5 % 2); /* mod operaion */
}
